css:
.sl-cta-minimal {
    padding-block: clamp(4rem, 8vw, 7rem);
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-cta-minimal .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-cta-minimal.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; }

.sl-cta-minimal .sl-minimal-heading {
    font-weight: 800;
    letter-spacing: -0.03em;
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-cta-minimal .sl-btn-minimal {
    color: var(--smartlearn-primary);
    padding-bottom: 6px;
    background-image: linear-gradient(currentColor, currentColor);
    background-repeat: no-repeat;
    background-position: 0 100%;
    background-size: 0% 2px;
    transition: color 0.25s ease, background-size 0.3s ease;
}
[dir="rtl"] .sl-cta-minimal .sl-btn-minimal {
    background-position: 100% 100%;
}
.sl-cta-minimal .sl-btn-minimal::after {
    content: "→";
    display: inline-block;
    transition: transform 0.25s ease;
}
[dir="rtl"] .sl-cta-minimal .sl-btn-minimal::after {
    transform: scaleX(-1);
}
.sl-cta-minimal .sl-btn-minimal:hover,
.sl-cta-minimal .sl-btn-minimal:focus-visible {
    color: var(--smartlearn-primary-hover, var(--smartlearn-primary));
    background-size: 100% 2px;
}
.sl-cta-minimal .sl-btn-minimal:hover::after,
.sl-cta-minimal .sl-btn-minimal:focus-visible::after {
    transform: translateX(4px);
}
[dir="rtl"] .sl-cta-minimal .sl-btn-minimal:hover::after,
[dir="rtl"] .sl-cta-minimal .sl-btn-minimal:focus-visible::after {
    transform: scaleX(-1) translateX(4px);
}
.sl-cta-minimal .sl-btn-minimal:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 4px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-cta-minimal .sl-btn-minimal,
    .sl-cta-minimal .sl-btn-minimal::after { transition: none; }
    .sl-cta-minimal .sl-btn-minimal:hover::after,
    .sl-cta-minimal .sl-btn-minimal:focus-visible::after { transform: none; }
    [dir="rtl"] .sl-cta-minimal .sl-btn-minimal:hover::after,
    [dir="rtl"] .sl-cta-minimal .sl-btn-minimal:focus-visible::after { transform: scaleX(-1); }
}
